UPDATE ar_ling_root_lemma_furuq_set SET canonical_en = 'Coming down and sending down', canonical_ar = 'النُّزُولُ وَالإِنْزَالُ', updated_at = datetime('now') WHERE id = 'NS:TO:TO_DESCEND_TO_REVEAL_COME_DOWN' AND canonical_en = 'Sending down: نَزَّلَ and أَنْزَلَ';
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'ذَنْب looks at what follows the deed; إِثْم at how it holds you back from good, and it is deliberate; خَطِيئَة at missing the aim; خِطْء is a wrong done on purpose; جُنَاح at leaning off the right path; حُوب is a big wrong people are warned off; حِنْث a sin that makes you guilty, first a broken oath; إِجْرَام a wrong you earn; لَمَم coming close to sin — the small ones. — al-Rāghib pp. 331, 63, 287, 206, 261, 260, 192, 746; Lisān pp. 65, 337, 942; Maqāyīs pp. 39, 53; Lane pp. 980, 22' WHERE id = 'NSS:NS:SIN:SIN:contrast';
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'عِقَاب is the payback that comes after the deed; عَذَاب is the pain itself; نَكَال is punishment made an example to scare others off, and مَثُلَات are such punishments that left past peoples as a lesson; بَأْس is hard force that strikes; نَكِير is God acting against them to stop them; وَبَال is the heavy, bad end of one’s own deed. — Maqāyīs pp. 18, 87; al-Rāghib pp. 554, 824, 758, 153, 823; al-Miṣbāḥ p.3201; Lane pp. 2850, 3048' WHERE id = 'NSS:NS:PUNISHMENT:PUNISHMENT:contrast';
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'رَجَعَ is the plain word for going back to where you began; تَابَ is turning back from sin; أَنَابَ is turning to God again and again, sincerely; إِيَاب is coming back by choice, like a traveller home; فَاءَ is coming back to a good state; بَاءَ is coming back loaded with what is against you; صَدَرَ is going back from the water; اِرْتَدَّ is going back the way you came, often from faith; صَارَ is where a thing ends up. — al-Rāghib pp. 342, 169, 827, 97, 650, 477, 348, 498; Maqāyīs p.33; al-Ṣiḥāḥ p.57; Lisān p.2405' WHERE id = 'NSS:NS:TO:TO_RETURN:contrast';
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'طَوْل is bounty with reach and power behind it; سَعَة is roominess, having enough; فَضْل is the extra given beyond what is owed; مَيْسَرَة is the easy time when you have enough to pay; بَسْطَة is room spread wide, in body or knowledge. — al-Rāghib pp. 533, 639, 891, 122; Lisān pp. 4240, 2879; Lane p.204' WHERE id = 'NSS:NS:SUFFICIENT:SUFFICIENT:contrast';
UPDATE ar_ling_root_lemma_furuq_set_src SET note_md = 'نَزَلَ is coming down by itself; أَنْزَلَ is the general word for sending down, and نَزَّلَ is piece by piece, over time (al-Rāghib, al-Zamakhsharī, al-Rāzī; Abū Ḥayyān, Ibn ʿĀshūr and al-Ālūsī doubt the rule, see 25:32); تَنَزَّلَ is said of angels and devils coming down, never of God; حَلَّ is coming down to stay; هَبَطَ is going down by force — for people, a lowering, not an honour. — al-Rāghib pp. 799, 251, 832; Maqāyīs p.128; Lane pp. 3031, 618; at 3:3: al-Kashshāf, al-Rāzī p.137, Abū Ḥayyān, Ibn ʿĀshūr p.147, al-Ālūsī p.76' WHERE id = 'NSS:NS:TO:TO_DESCEND_TO_REVEAL_COME_DOWN:contrast';
